1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { logActivity } from "@/lib/activity-log";
6	
7	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
8	
9	async function postPurchaseJournal(
10	  supabase: SupabaseServerClient,
11	  businessId: string,
12	  date: string,
13	  description: string,
14	  amount: number,
15	  paidAmount: number,
16	) {
17	  const lines: { account_code: string; debit: number; credit: number }[] = [
18	    { account_code: "1-200", debit: amount, credit: 0 },
19	  ];
20	  if (paidAmount > 0) {
21	    lines.push({ account_code: "1-001", debit: 0, credit: paidAmount });
22	  }
23	  const sisaUtang = amount - paidAmount;
24	  if (sisaUtang > 0) {
25	    lines.push({ account_code: "2-001", debit: 0, credit: sisaUtang });
26	  }
27	  await supabase.rpc("post_journal_entry", {
28	    p_business_id: businessId,
29	    p_date: date,
30	    p_description: description,
31	    p_lines: lines,
32	  });
33	}
34	
35	export type AddPurchaseState = { error: string | null };
36	
37	export async function addPurchase(
38	  businessId: string,
39	  _prevState: AddPurchaseState,
40	  formData: FormData,
41	): Promise<AddPurchaseState> {
42	  const supplierId = (formData.get("supplierId") as string) || null;
43	  const date = formData.get("date") as string;
44	  const category = formData.get("category") as string;
45	  const note = (formData.get("note") as string)?.trim();
46	  const amountRaw = formData.get("amount") as string;
47	  const paidAmountRaw = formData.get("paidAmount") as string;
48	  const qtyRaw = formData.get("qty") as string;
49	
50	  if (!date) {
51	    return { error: "Tanggal wajib diisi." };
52	  }
53	  if (category !== "Bahan Baku" && category !== "Barang Dagang") {
54	    return { error: "Kategori tidak valid." };
55	  }
56	
57	  const amount = Number(amountRaw);
58	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
59	    return { error: "Total pembelian harus angka lebih dari 0." };
60	  }
61	
62	  const paidAmount = paidAmountRaw ? Number(paidAmountRaw) : 0;
63	  if (Number.isNaN(paidAmount) || paidAmount < 0) {
64	    return { error: "Jumlah dibayar harus angka dan tidak boleh negatif." };
65	  }
66	  if (paidAmount > amount) {
67	    return { error: "Jumlah dibayar tidak boleh lebih besar dari total pembelian." };
68	  }
69	
70	  const qty = Number(qtyRaw);
71	  if (!qtyRaw || Number.isNaN(qty) || qty <= 0) {
72	    return { error: "Qty dibeli harus angka lebih dari 0." };
73	  }
74	
75	  const supabase = await createClient();
76	
77	  let ingredientId: string | null = null;
78	  let productId: string | null = null;
79	  let itemName = "";
80	
81	  if (category === "Bahan Baku") {
82	    ingredientId = formData.get("ingredientId") as string;
83	    if (!ingredientId) {
84	      return { error: "Pilih bahan yang dibeli." };
85	    }
86	
87	    const { data: ingredient } = await supabase
88	      .from("ingredients")
89	      .select("id, name, business_id, stock, unit_cost")
90	      .eq("id", ingredientId)
91	      .single();
92	
93	    if (!ingredient || ingredient.business_id !== businessId) {
94	      return { error: "Bahan baku tidak ditemukan." };
95	    }
96	    itemName = ingredient.name;
97	
98	    const oldValue = Number(ingredient.stock) * Number(ingredient.unit_cost);
99	    const newStock = Number(ingredient.stock) + qty;
100	    const newUnitCost =
101	      newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(ingredient.unit_cost);
102	
103	    const { error: updateError } = await supabase
104	      .from("ingredients")
105	      .update({ stock: newStock, unit_cost: newUnitCost })
106	      .eq("id", ingredientId);
107	
108	    if (updateError) {
109	      return { error: updateError.message };
110	    }
111	
112	    if (newUnitCost !== Number(ingredient.unit_cost)) {
113	      await supabase.from("ingredient_price_history").insert({
114	        business_id: businessId,
115	        ingredient_id: ingredientId,
116	        unit_cost: newUnitCost,
117	        source: "pembelian",
118	      });
119	    }
120	  } else {
121	    productId = formData.get("productId") as string;
122	    if (!productId) {
123	      return { error: "Pilih produk yang dibeli." };
124	    }
125	
126	    const { data: product } = await supabase
127	      .from("products")
128	      .select("id, name, business_id, stock, cost")
129	      .eq("id", productId)
130	      .single();
131	
132	    if (!product || product.business_id !== businessId) {
133	      return { error: "Produk tidak ditemukan." };
134	    }
135	    itemName = product.name;
136	
137	    const oldValue = Number(product.stock) * Number(product.cost);
138	    const newStock = Number(product.stock) + qty;
139	    const newCost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(product.cost);
140	
141	    const { error: updateError } = await supabase
142	      .from("products")
143	      .update({ stock: newStock, cost: newCost })
144	      .eq("id", productId);
145	
146	    if (updateError) {
147	      return { error: updateError.message };
148	    }
149	  }
150	
151	  const { error } = await supabase.from("purchases").insert({
152	    business_id: businessId,
153	    supplier_id: supplierId,
154	    date,
155	    category,
156	    ingredient_id: ingredientId,
157	    product_id: productId,
158	    qty,
159	    note: note || null,
160	    amount,
161	    paid_amount: paidAmount,
162	  });
163	
164	  if (error) {
165	    return { error: error.message };
166	  }
167	
168	  await postPurchaseJournal(supabase, businessId, date, `Pembelian: ${itemName}`, amount, paidAmount);
169	
170	  await logActivity(
171	    supabase,
172	    businessId,
173	    "produk",
174	    "sukses",
175	    `Pembelian: ${itemName}`,
176	    `Rp${amount.toLocaleString("id-ID")}${paidAmount < amount ? " · sebagian/seluruhnya utang" : " · lunas"}`,
177	  );
178	
179	  revalidatePath(`/business/${businessId}/purchases`);
180	  revalidatePath(`/business/${businessId}/suppliers`);
181	  return { error: null };
182	}
183	
184	export type AddPaymentState = { error: string | null };
185	
186	export async function addPurchasePayment(
187	  businessId: string,
188	  purchaseId: string,
189	  _prevState: AddPaymentState,
190	  formData: FormData,
191	): Promise<AddPaymentState> {
192	  const date = formData.get("date") as string;
193	  const amountRaw = formData.get("amount") as string;
194	  const note = (formData.get("note") as string)?.trim();
195	
196	  if (!date) {
197	    return { error: "Tanggal wajib diisi." };
198	  }
199	
200	  const amount = Number(amountRaw);
201	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
202	    return { error: "Jumlah bayar harus angka lebih dari 0." };
203	  }
204	
205	  const supabase = await createClient();
206	
207	  const { data: purchase } = await supabase
208	    .from("purchases")
209	    .select("id, business_id, amount, paid_amount, ingredient_id, product_id")
210	    .eq("id", purchaseId)
211	    .eq("business_id", businessId)
212	    .single();
213	
214	  if (!purchase) {
215	    return { error: "Data pembelian tidak ditemukan." };
216	  }
217	
218	  const sisaUtang = Number(purchase.amount) - Number(purchase.paid_amount);
219	  if (amount > sisaUtang) {
220	    return { error: `Jumlah bayar melebihi sisa utang (${sisaUtang.toLocaleString("id-ID")}).` };
221	  }
222	
223	  const newPaidAmount = Number(purchase.paid_amount) + amount;
224	
